-- ==============================================================================
-- EnercoOS Hyprland Lua Configuration
-- Theme: macOS Cupertino Enterprise Workstation (PT Mega Tama Enerco)
-- Tested & Verified for Hyprland 0.57+
-- ==============================================================================

-- Explicitly disable autogenerated warning banner
hl.config({
    autogenerated = false,
})

-- Monitors (Force 1:1 pixel rendering, prefer 1080p for modern displays & VMs)
hl.monitor({
    output   = "",
    mode     = "1920x1080@60",
    position = "auto",
    scale    = 1,
})
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = 1,
})

-- Default applications
local terminal    = "kitty"
local fileManager = "thunar"
local menu        = "qs -c MacShell ipc call spotlight toggle || rofi -show drun"

-- Enterprise Autostart Services
hl.on("hyprland.start", function ()
    hl.exec_cmd("pgrep -f polkit-gnome >/dev/null || /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1 &")
    hl.exec_cmd("pgrep -x swaybg >/dev/null || swaybg -i /usr/share/backgrounds/enerco-mac.png -m fill &")
    hl.exec_cmd("/usr/local/bin/macshell-start &")
    hl.exec_cmd("pgrep -x hypridle >/dev/null || hypridle &")
    hl.exec_cmd("pgrep -f blueman-applet >/dev/null || blueman-applet &")
    hl.exec_cmd("pgrep -f enerco-welcome >/dev/null || /usr/local/bin/enerco-welcome &")
    -- VirtualBox Guest Services (Auto-resize display, clipboard, seamless mouse)
    hl.exec_cmd("pgrep -f VBoxClient >/dev/null || VBoxClient-all &")
    hl.exec_cmd("hyprctl keyword monitor ',1920x1080@60,auto,1' 2>/dev/null || true")
    -- macOS Desktop Appearance & Traffic Lights
    hl.exec_cmd("gsettings set org.gnome.desktop.interface icon-theme 'MacOS-Like-Dark' 2>/dev/null || true")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme 'capitaine-cursors' 2>/dev/null || true")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-name 'Inter 11' 2>/dev/null || true")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme 'prefer-dark' 2>/dev/null || true")
    hl.exec_cmd("gsettings set org.gnome.desktop.wm.preferences button-layout 'close,minimize,maximize:' 2>/dev/null || true")
end)

-- Environment Variables
hl.env("XCURSOR_THEME", "capitaine-cursors")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_THEME", "capitaine-cursors")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("GTK_THEME", "Adwaita:dark")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QS_ICON_THEME", "MacOS-Like-Dark")

-- Look and Feel (macOS Tahoe Aesthetics)
hl.config({
    general = {
        gaps_in  = 6,
        gaps_out = 12,
        border_size = 1,
        col = {
            active_border   = "rgba(ffffff45)",
            inactive_border = "rgba(ffffff15)",
        },
        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    decoration = {
        rounding = 14,
        rounding_power = 2,
        active_opacity   = 0.98,
        inactive_opacity = 0.92,
        shadow = {
            enabled      = true,
            range        = 30,
            render_power = 3,
            color        = 0x66000000,
        },
        blur = {
            enabled           = true,
            size              = 6,
            passes            = 2,
            vibrancy          = 0.3,
            new_optimizations = true,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Cupertino Animation Curves
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 280, damping = 26 })

hl.animation({ leaf = "global",     enabled = true,  speed = 8,   bezier = "default" })
hl.animation({ leaf = "border",     enabled = true,  speed = 5,   bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",    enabled = true,  speed = 4,   spring = "easy" })
hl.animation({ leaf = "windowsIn",  enabled = true,  speed = 3.5, spring = "easy",   style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true,  speed = 2,   bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn",     enabled = true,  speed = 2,   bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",    enabled = true,  speed = 2,   bezier = "almostLinear" })
hl.animation({ leaf = "fade",       enabled = true,  speed = 2.5, bezier = "quick" })
hl.animation({ leaf = "layers",     enabled = true,  speed = 3.5, bezier = "easeOutQuint" })

-- Layout & Input
hl.config({
    dwindle = {
        preserve_split = true,
    },
    master = {
        new_status = "master",
    },
    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo   = true,
        vrr                     = 0,
    },
    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = {
            natural_scroll = true,
            tap_to_click = true,
            clickfinger_behavior    = true,
            tap_and_drag            = true,
            drag_lock               = false,
            scroll_factor           = 1.0,
            middle_button_emulation = true,
        },
    },
    gestures = {
        workspace_swipe_distance                 = 300,
        workspace_swipe_invert                   = true,
        workspace_swipe_min_speed_to_force       = 30,
        workspace_swipe_cancel_ratio             = 0.5,
        workspace_swipe_create_new               = true,
        workspace_swipe_direction_lock           = true,
        workspace_swipe_direction_lock_threshold = 10,
        workspace_swipe_forever                  = true,
    },
})

-- macOS 3-Finger Spaces Swipe Navigation
hl.gesture({
    fingers   = 3,
    direction = "horizontal",
    action    = "workspace",
})

-- Keybindings
local mainMod = "SUPER"

-- macOS Native Keybindings & MacShell Controls
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + space",  hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + PERIOD", hl.dsp.exec_cmd("qs -c MacShell ipc call spotlight emoji"))
hl.bind(mainMod .. " + Z",      hl.dsp.exec_cmd("qs -c MacShell ipc call settings toggle"))
hl.bind(mainMod .. " + W",      hl.dsp.window.close())
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + Tab",    hl.dsp.exec_cmd("rofi -show window"))
hl.bind(mainMod .. " + D",      hl.dsp.exec_cmd("hyprctl dispatch togglespecialworkspace"))
hl.bind(mainMod .. " + L",      hl.dsp.exec_cmd("/usr/local/bin/maclock"))
hl.bind(mainMod .. " + B",      hl.dsp.exec_cmd("/usr/local/bin/enerco-mterp"))
hl.bind(mainMod .. " + I",      hl.dsp.exec_cmd("/usr/local/bin/enerco-installer"))
hl.bind(mainMod .. " + M",      hl.dsp.exit())
hl.bind(mainMod .. " + V",      hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + J",      hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd('grim -g "$(slurp)" - | wl-copy'))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("/usr/local/bin/macshell-start &"))

-- Hardware Audio & Brightness Media Keys (PipeWire / WirePlumber / brightnessctl)
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"))
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"))
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"))
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl set +5%"))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"))

-- Navigation (Focus)
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Workspaces 1-10
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Mouse Window Control
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Resolution Switchers for Virtual Machines & Displays
hl.bind(mainMod .. " + F11", hl.dsp.exec_cmd("hyprctl keyword monitor ',1920x1080@60,auto,1'"))
hl.bind(mainMod .. " + F10", hl.dsp.exec_cmd("hyprctl keyword monitor ',1366x768@60,auto,1'"))
hl.bind(mainMod .. " + F9",  hl.dsp.exec_cmd("hyprctl keyword monitor ',1280x800@60,auto,1'"))
hl.bind(mainMod .. " + F8",  hl.dsp.exec_cmd("hyprctl keyword monitor ',preferred,auto,1'"))

-- Layer Rules for MacShell Dark Glass Blur & Waybar Fallback
hl.layer_rule({
    name         = "blur-macbarbg",
    match        = { namespace = "macbarbg" },
    blur         = true,
    ignore_alpha = 0.05,
})

hl.layer_rule({
    name         = "blur-macdock",
    match        = { namespace = "macdock" },
    blur         = true,
    ignore_alpha = 0.2,
})

hl.layer_rule({
    name         = "blur-macspot",
    match        = { namespace = "macspot" },
    blur         = true,
    ignore_alpha = 0.05,
})

hl.layer_rule({
    name         = "blur-maclock",
    match        = { namespace = "quickshell:MacLock" },
    blur         = true,
    ignore_alpha = 0.05,
})

hl.layer_rule({
    name         = "blur-waybar",
    match        = { namespace = "waybar" },
    blur         = true,
    ignore_alpha = 0.2,
})

-- Enterprise Window Rules
hl.window_rule({
    name   = "float-calamares",
    match  = { class = "calamares" },
    float  = true,
    size   = "840 520",
    center = true,
})

hl.window_rule({
    name   = "float-pavucontrol",
    match  = { class = "org.pulseaudio.pavucontrol" },
    float  = true,
    size   = "640 440",
    center = true,
})

hl.window_rule({
    name   = "float-blueman",
    match  = { class = "blueman-manager" },
    float  = true,
    size   = "640 440",
    center = true,
})

hl.window_rule({
    name   = "float-wdisplays",
    match  = { class = "wdisplays" },
    float  = true,
    size   = "720 480",
    center = true,
})

hl.window_rule({
    name  = "float-zenity",
    match = { class = "zenity" },
    float = true,
})

hl.window_rule({
    name   = "float-welcome",
    match  = { title = "EnercoOS Workstation" },
    float  = true,
    center = true,
})
